public class InheritancePointTester1 {
	public static void main(String[] args) {
		Point p = new Point(1, 2);
	    System.out.println(p);  
	    Point3D p3d = new Point3D(11, 12, 13);
	    System.out.println(p3d);
	}
}
//Khatwa 1: Ta'reef al-class Point
class Point {
	//Khatwa 1.1: Ilan al-instance variables
	private int x;
	private int y;
	//Khatwa 1.2: Ta'reef al-constructor li-insa' nuqta ma'a al-xy-coordinate al-muwahidi
	public Point(int x, int y) {
		this.x = x;
	    this.y = y;
	}
	//Khatwa 1.3: Ta'reef method toString li-husool ala tamtheel string li-instance al-Point
	public String toString() {
	    return "(" + x + ", " + y + ")";
	}
	//Khatwa 1.4: Ta'reef getter methods li-husool ala al-xy-coordinate lil-nuqta
	public int getX() {
		return x;
	}
	public int getY() {
		return y;
	}		
}
//Khatwa 2: Tawsia al-class Point li-ta'reef al-class Point3D
class Point3D extends Point {
	//Khatwa 2.1: Ilan mutaghayyir al-instance
	private int z;
	//Khatwa 2.2: Ta'reef al-constructor li-insa' nuqta 3D ma'a al-xyz-coordinates al-muwahada
	public Point3D(int x, int y, int z) {
		super(x, y);
	    this.z = z;
	}
	//Khatwa 2.3: Ta'reef al-method li-husool ala al-z-coordinate lil-nuqta 3D
	public int getZ() {
		return z;
	}		
	//Khatwa 2.4: Override method toString min al-class Point li-husool ala tamtheel string li-instance Point3D
	public String toString() {
	    return "(" + super.getX() + "," + super.getY() + "," + this.z + ")";
	}
}
